import{a as o,_ as e}from"./chunks/工作台.DlQUlLGO.js";import{_ as t,o as d,c as r,a2 as i}from"./chunks/framework.CqGPl1zp.js";const l="/newx-doc/img/OA%E5%8D%8F%E5%90%8C%E5%8A%9E%E5%85%AC/%E7%A7%BB%E5%8A%A8%E7%AB%AF/%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",c="/newx-doc/img/ad/zsxq_oa.png",g=JSON.parse('{"title":"OA 演示","description":"","frontmatter":{},"headers":[],"relativePath":"oa-preview.md","filePath":"oa-preview.md","lastUpdated":null}'),n={name:"oa-preview.md"};function h(u,a,p,_,s,m){return d(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="oa-演示" tabindex="-1">OA 演示 <a class="header-anchor" href="#oa-演示" aria-label="Permalink to &quot;OA 演示&quot;">​</a></h1><h2 id="_1-演示地址" tabindex="-1">1. 演示地址 <a class="header-anchor" href="#_1-演示地址" aria-label="Permalink to &quot;1. 演示地址&quot;">​</a></h2><p>OA（Office Automation，办公自动化）用于企业日常协作和行政办公，提供日程、任务、计划、汇报、公告、讨论、通讯录、笔记、企业邮箱、企业云盘、公文和各类办公申请。</p><h3 id="_1-1-oa-管理后台" tabindex="-1">1.1 OA 管理后台 <a class="header-anchor" href="#_1-1-oa-管理后台" aria-label="Permalink to &quot;1.1 OA 管理后台&quot;">​</a></h3><ul><li>演示地址：<a href="http://dashboard-vue3.yudao.iocoder.cn/" target="_blank" rel="noreferrer">http://dashboard-vue3.yudao.iocoder.cn/</a></li><li>菜单：&quot;OA 办公协同&quot;下的「工作台」「考勤管理」「公告管理」「任务管理」「日程管理」「工作计划」等菜单</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>oa</code> 目录，基于 Vue3 + Element Plus 实现</li></ul><p>工作台展示今日考勤、通讯录、讨论区、待办任务、公告通知、工作计划和行事历。点击卡片或【更多】，可以进入对应业务页面。</p><p><img src="'+o+'" alt="管理后台"></p><p>工作台对应 <code>@/views/oa/home/index.vue</code>，各区块分别调用考勤、通讯录、讨论、任务、公告、计划和日程接口。</p><h3 id="_1-2-oa-后端" tabindex="-1">1.2 OA 后端 <a class="header-anchor" href="#_1-2-oa-后端" aria-label="Permalink to &quot;1.2 OA 后端&quot;">​</a></h3><p>支持 Spring Boot 单体、Spring Cloud 微服务架构</p><ul><li>单体仓库：<a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 的 <code>yudao-module-oa</code> 模块</li><li>微服务仓库：<a href="https://github.com/YunaiV/yudao-cloud" target="_blank" rel="noreferrer">https://github.com/YunaiV/yudao-cloud</a> 的 <code>yudao-module-oa</code> 服务</li></ul><p>后台用户、部门和权限复用 System 模块，文件上传复用 Infra 模块，办公申请的审批复用 BPM 模块。</p><h3 id="_1-3-oa-移动端" tabindex="-1">1.3 OA 移动端 <a class="header-anchor" href="#_1-3-oa-移动端" aria-label="Permalink to &quot;1.3 OA 移动端&quot;">​</a></h3><p>OA 提供 uni-app 移动端，协作、办公、行政和流程申请均已迁到手机端，详见 <a href="./oa/mobile">《移动端 OA》</a>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a> 的 <code>pages-oa</code> 目录</li></ul><p><img src="'+l+'" alt="移动端"></p><h2 id="_2-oa-启动" tabindex="-1">2. OA 启动 <a class="header-anchor" href="#_2-oa-启动" aria-label="Permalink to &quot;2. OA 启动&quot;">​</a></h2><p>参见 <a href="./oa/build">《OA 手册 —— 功能开启》</a> 文档。</p><h2 id="_3-oa-交流" tabindex="-1">3. OA 交流 <a class="header-anchor" href="#_3-oa-交流" aria-label="Permalink to &quot;3. OA 交流&quot;">​</a></h2><p>专属交流社区，欢迎扫码加入。</p><p><img src="'+c+'" alt="知识星球"></p><h2 id="_4-功能描述" tabindex="-1">4. 功能描述 <a class="header-anchor" href="#_4-功能描述" aria-label="Permalink to &quot;4. 功能描述&quot;">​</a></h2><p>主要分为日常协作、办公服务、行政管理和流程申请四类，工作台汇总本人需要处理的信息。</p><ul><li><strong>日常协作</strong>：日程、任务、工作计划、工作汇报、公告、讨论、通讯录和笔记。</li><li><strong>办公服务</strong>：企业邮箱、企业云盘。</li><li><strong>行政管理</strong>：办公用品、用印、会议室和车辆。</li><li><strong>流程申请</strong>：公文、出差、费用报销、请假、加班、转正和离职。</li></ul><p><img src="'+e+'" alt="OA 功能列表"></p><p>办公申请通常先保存草稿，再从列表提交审批。审批通过后的业务操作随场景不同：用品需要实际发放，会议室需要开始和完成使用，车辆还需要提交还车申请。</p><h2 id="_5-表结构" tabindex="-1">5. 表结构 <a class="header-anchor" href="#_5-表结构" aria-label="Permalink to &quot;5. 表结构&quot;">​</a></h2><p>OA 共 <strong>48</strong> 张表，表名统一以 <code>oa_</code> 为前缀。</p><table tabindex="0"><thead><tr><th>模块</th><th>子前缀</th><th>表数量</th><th>核心职责</th></tr></thead><tbody><tr><td>工作协作</td><td><code>oa_schedule*</code>、<code>oa_task*</code>、<code>oa_plan</code>、<code>oa_work_report</code></td><td>7</td><td>日程、参与人、任务、反馈、计划和汇报</td></tr><tr><td>信息协作</td><td><code>oa_announcement*</code>、<code>oa_discussion*</code>、<code>oa_vote*</code>、<code>oa_contact*</code>、<code>oa_note*</code></td><td>13</td><td>公告接收、讨论投票、联系人和笔记共享</td></tr><tr><td>企业邮箱</td><td><code>oa_mail_*</code></td><td>4</td><td>服务、个人账号、文件夹和邮件</td></tr><tr><td>企业云盘</td><td><code>oa_file_*</code></td><td>3</td><td>文件节点、共享权限和收藏</td></tr><tr><td>办公用品与用印</td><td><code>oa_supply_*</code>、<code>oa_seal*</code></td><td>5</td><td>用品、申请明细、发放归还、印章和用印申请</td></tr><tr><td>会议室与车辆</td><td><code>oa_meeting_room*</code>、<code>oa_vehicle*</code></td><td>5</td><td>资源资料、会议室预定、用车和还车</td></tr><tr><td>公文管理</td><td><code>oa_official_doc_*</code></td><td>3</td><td>套红模板、发文和收文</td></tr><tr><td>出差与报销</td><td><code>oa_travel_*</code>、<code>oa_reimbursement</code></td><td>3</td><td>出差申请、差旅报销和普通费用报销</td></tr><tr><td>考勤与人事申请</td><td><code>oa_attendance</code>、<code>oa_leave_apply</code>、<code>oa_overtime_apply</code>、<code>oa_regular_apply</code>、<code>oa_resign_apply</code></td><td>5</td><td>打卡、考勤统计和四类人事申请</td></tr></tbody></table><h3 id="_5-1-日常协作" tabindex="-1">5.1 日常协作 <a class="header-anchor" href="#_5-1-日常协作" aria-label="Permalink to &quot;5.1 日常协作&quot;">​</a></h3><p>日程按创建人和参与人共享；任务记录各接收人的进度和反馈；计划提供管理范围内的报表与点评；工作汇报按日报、周报、月报统计填写情况。</p><p>公告保存接收人的阅读状态，讨论区支持回复、点赞和投票。联系人和笔记通过共享关系开放给其他用户。</p><ul><li><a href="./oa/collaboration/work">《【协作】日程、任务、计划与汇报》</a></li><li><a href="./oa/collaboration/communication">《【协作】公告、讨论、通讯录与笔记》</a></li></ul><h3 id="_5-2-办公服务" tabindex="-1">5.2 办公服务 <a class="header-anchor" href="#_5-2-办公服务" aria-label="Permalink to &quot;5.2 办公服务&quot;">​</a></h3><p>企业邮箱对接 IMAP、SMTP 服务，用户绑定个人账号后收发邮件；企业云盘通过文件目录和用户、部门授权维护共享范围。</p><ul><li><a href="./oa/mail">《【办公】企业邮箱》</a></li><li><a href="./oa/file">《【办公】企业云盘》</a></li></ul><h3 id="_5-3-行政管理" tabindex="-1">5.3 行政管理 <a class="header-anchor" href="#_5-3-行政管理" aria-label="Permalink to &quot;5.3 行政管理&quot;">​</a></h3><p>办公用品在发放时扣库存、归还时补库存；用印申请关联印章资料。会议室预定检查时间和成员范围，用车与还车通过两张申请单关联。</p><ul><li><a href="./oa/administration/supply-seal">《【行政】办公用品、用印管理》</a></li><li><a href="./oa/administration/meeting-vehicle">《【行政】会议室、车辆管理》</a></li></ul><h3 id="_5-4-流程申请" tabindex="-1">5.4 流程申请 <a class="header-anchor" href="#_5-4-流程申请" aria-label="Permalink to &quot;5.4 流程申请&quot;">​</a></h3><p>公文按套红模板、发文和收文组织。差旅报销可关联已通过的出差申请，普通费用报销单独保存费用明细。请假、加班、转正和离职申请分别记录业务资料，审批使用 BPM 流程。</p><ul><li><a href="./oa/official-doc">《【流程】公文管理》</a></li><li><a href="./oa/travel-reimbursement">《【流程】出差、费用报销》</a></li><li><a href="./oa/attendance-application">《【流程】考勤、请假、加班、转正与离职》</a></li></ul>',42)])])}const A=t(n,[["render",h]]);export{g as __pageData,A as default};
